 22	// GenerateFromTranscript generates a summary from raw transcript bytes.
 23	// This is the shared implementation used by both explain --generate and auto-summarize.
 24	//
 25	// Parameters:
 26	//   - ctx: context for cancellation
 27	//   - transcriptBytes: raw transcript bytes (JSONL or JSON format depending on agent)
 28	//   - filesTouched: list of files modified during the session
 29	//   - agentType: the agent type to determine transcript format
 30	//   - generator: summary generator to use (if nil, uses default ClaudeGenerator)
 31	//
 32	// Returns nil, error if transcript is empty or cannot be parsed.
 33	func GenerateFromTranscript(ctx context.Context, transcriptBytes []byte, filesTouched []string, agentType types.AgentType, generator Generator) (*checkpoint.Summary, error) {
 34		if len(transcriptBytes) == 0 {
 35			return nil, errors.New("empty transcript")
 36		}
 37	
 38		// Build condensed transcript for summarization
 39		condensed, err := BuildCondensedTranscriptFromBytes(transcriptBytes, agentType)
 40		if err != nil {
 41			return nil, fmt.Errorf("failed to parse transcript: %w", err)
 42		}
 43		if len(condensed) == 0 {
 44			return nil, errors.New("transcript has no content to summarize")
 45		}
 46	
 47		input := Input{
 48			Transcript:   condensed,
 49			FilesTouched: filesTouched,
 50		}
 51	
 52		// Use default generator if none provided
 53		if generator == nil {
 54			generator = &ClaudeGenerator{}
 55		}
 56	
 57		summary, err := generator.Generate(ctx, input)
 58		if err != nil {
 59			return nil, fmt.Errorf("failed to generate summary: %w", err)
 60		}
 61	
 62		return summary, nil
 63	}
